var d = tree.root.get_node_or_null("/root/AbilityChoiceDialog")
if d != null and d.visible:
	d.get_ok_button().pressed.emit()
return "ok"

var scr = tree.current_scene.get_node("HUD_Right/VBoxContainer/ShootingScrollContainer")
var b = tree.current_scene.get_node("HUD_Right/VBoxContainer/ShootingScrollContainer").get_node("ShootingPanel/DeclarationBox").get_node_or_null("StartActionButton")
if b == null:
	return "StartActionButton missing"
var br = b.get_global_rect()
var sr = scr.get_global_rect()
return br.position.y >= sr.position.y - 1.0 and br.end.y <= sr.end.y + 1.0

var f = tree.root.gui_get_focus_owner()
if f == null:
	return "none"
return str(f.text) if ("text" in f) else str(f.name)

